select
  id, user_id, user_type, record_id, status, msg_type, msg_content, to_address, to_user_name, send_time, send_state, create_time
from sys_message

    
        and id = #{id}
    
    
        and user_id = #{userId}
    
    
        and user_type = #{userType}
    
    
        and record_id = #{recordId}
    
    
        and status = #{status}
    
    
        and msg_type = #{msgType}
    
    
        and msg_content = #{msgContent}
    
    
        and to_address = #{toAddress}
    
    
        and to_user_name = #{toUserName}
    
    
        and send_time = #{sendTime}
    
    
        and send_state = #{sendState}
    
    
        and create_time = #{createTime}
    

limit #{pageable.offset}, #{pageable.pageSize}

